window.HSK_TOPICS = [{"id": "t-congso", "title": "Công sở", "hz": "办公", "desc": "Từ vựng dùng hằng ngày ở văn phòng: chức vụ, họp hành, lương thưởng, giấy tờ.", "groups": [{"name": "Nơi làm việc", "items": [{"id": "h2-294", "ex": {"zh": "我在一家外国公司工作。", "py": "Wǒ zài yì jiā wàiguó gōngsī gōngzuò.", "vi": "Tôi làm việc ở một công ty nước ngoài."}}, {"id": "h2-110", "ex": {"zh": "经理的办公室在五楼。", "py": "Jīnglǐ de bàngōngshì zài wǔ lóu.", "vi": "Văn phòng của giám đốc ở tầng năm."}}, {"id": "h0-0001", "ex": {"zh": "下午两点在三楼会议室开会。", "py": "Xiàwǔ liǎng diǎn zài sān lóu huìyìshì kāihuì.", "vi": "Hai giờ chiều họp ở phòng họp tầng ba."}}, {"id": "h0-0002", "ex": {"zh": "请把文件放在我的办公桌上。", "py": "Qǐng bǎ wénjiàn fàng zài wǒ de bàngōngzhuō shang.", "vi": "Hãy để tài liệu lên bàn làm việc của tôi."}}, {"id": "h3-068", "ex": {"zh": "你在哪个部门工作？", "py": "Nǐ zài nǎge bùmén gōngzuò?", "vi": "Bạn làm ở phòng ban nào?"}}, {"id": "h2-203", "ex": {"zh": "我们单位离家很近，走路十分钟就到。", "py": "Wǒmen dānwèi lí jiā hěn jìn, zǒulù shí fēnzhōng jiù dào.", "vi": "Cơ quan chúng tôi gần nhà, đi bộ mười phút là tới."}}, {"id": "h4-572", "ex": {"zh": "这是一家有三千名员工的大企业。", "py": "Zhè shì yì jiā yǒu sānqiān míng yuángōng de dà qǐyè.", "vi": "Đây là một doanh nghiệp lớn có ba nghìn nhân viên."}}, {"id": "h7-3259", "ex": {"zh": "客人来了，请先到前台登记。", "py": "Kèrén lái le, qǐng xiān dào qiántái dēngjì.", "vi": "Khách đến thì mời đăng ký ở quầy lễ tân trước."}}, {"id": "h1-224", "ex": {"zh": "你对现在的工作满意吗？", "py": "Nǐ duì xiànzài de gōngzuò mǎnyì ma?", "vi": "Bạn có hài lòng với công việc hiện tại không?"}}, {"id": "h1-416", "ex": {"zh": "我每天早上八点半上班。", "py": "Wǒ měi tiān zǎoshang bā diǎn bàn shàngbān.", "vi": "Hằng ngày tôi vào làm lúc tám rưỡi sáng."}}, {"id": "h1-490", "ex": {"zh": "今天事情不多，我们五点就能下班。", "py": "Jīntiān shìqing bù duō, wǒmen wǔ diǎn jiù néng xiàbān.", "vi": "Hôm nay ít việc, năm giờ là tan làm được."}}, {"id": "h4-371", "ex": {"zh": "这个月项目很忙，大家经常加班。", "py": "Zhège yuè xiàngmù hěn máng, dàjiā jīngcháng jiābān.", "vi": "Tháng này dự án bận, mọi người thường xuyên tăng ca."}}, {"id": "h6-1118", "ex": {"zh": "我们公司的总部在北京。", "py": "Wǒmen gōngsī de zǒngbù zài Běijīng.", "vi": "Trụ sở chính của công ty chúng tôi ở Bắc Kinh."}}, {"id": "h0-0009", "ex": {"zh": "公司在胡志明市开了一家分公司。", "py": "Gōngsī zài Húzhìmíng Shì kāi le yì jiā fēngōngsī.", "vi": "Công ty đã mở một chi nhánh ở TP. Hồ Chí Minh."}}, {"id": "h0-0010", "ex": {"zh": "新同事的工位就在我旁边。", "py": "Xīn tóngshì de gōngwèi jiù zài wǒ pángbiān.", "vi": "Chỗ ngồi làm việc của đồng nghiệp mới ngay cạnh tôi."}}]}, {"name": "Con người và chức vụ", "items": [{"id": "h2-647", "ex": {"zh": "我和同事们一起吃午饭。", "py": "Wǒ hé tóngshìmen yìqǐ chī wǔfàn.", "vi": "Tôi ăn trưa cùng các đồng nghiệp."}}, {"id": "h3-430", "ex": {"zh": "老板今天心情不错，表扬了我们。", "py": "Lǎobǎn jīntiān xīnqíng búcuò, biǎoyáng le wǒmen.", "vi": "Hôm nay sếp vui, đã khen chúng tôi."}}, {"id": "h2-400", "ex": {"zh": "这件事你得先问问王经理。", "py": "Zhè jiàn shì nǐ děi xiān wènwen Wáng jīnglǐ.", "vi": "Việc này bạn phải hỏi giám đốc Vương trước."}}, {"id": "h6-1120", "ex": {"zh": "总经理下周要来我们部门看看。", "py": "Zǒngjīnglǐ xià zhōu yào lái wǒmen bùmén kànkan.", "vi": "Tuần sau tổng giám đốc sẽ đến thăm phòng chúng ta."}}, {"id": "h3-457", "ex": {"zh": "这个方案领导已经同意了。", "py": "Zhège fāng'àn lǐngdǎo yǐjīng tóngyì le.", "vi": "Phương án này lãnh đạo đã đồng ý rồi."}}, {"id": "h7-3573", "ex": {"zh": "遇到问题，要及时告诉上司。", "py": "Yùdào wèntí, yào jíshí gàosu shàngsi.", "vi": "Gặp vấn đề thì phải báo cấp trên kịp thời."}}, {"id": "h7-4464", "ex": {"zh": "好的领导会关心自己的下属。", "py": "Hǎo de lǐngdǎo huì guānxīn zìjǐ de xiàshǔ.", "vi": "Lãnh đạo tốt sẽ quan tâm đến cấp dưới của mình."}}, {"id": "h3-870", "ex": {"zh": "公司给每个员工都买了保险。", "py": "Gōngsī gěi měi ge yuángōng dōu mǎi le bǎoxiǎn.", "vi": "Công ty mua bảo hiểm cho tất cả nhân viên."}}, {"id": "h7-5367", "ex": {"zh": "她是银行的普通职员。", "py": "Tā shì yínháng de pǔtōng zhíyuán.", "vi": "Cô ấy là nhân viên bình thường của ngân hàng."}}, {"id": "h4-513", "ex": {"zh": "有事请先跟我的秘书约时间。", "py": "Yǒu shì qǐng xiān gēn wǒ de mìshū yuē shíjiān.", "vi": "Có việc xin hẹn giờ trước với thư ký của tôi."}}, {"id": "h5-1038", "ex": {"zh": "经理让助理把会议记录发给大家。", "py": "Jīnglǐ ràng zhùlǐ bǎ huìyì jìlù fā gěi dàjiā.", "vi": "Giám đốc bảo trợ lý gửi biên bản cuộc họp cho mọi người."}}, {"id": "h5-1036", "ex": {"zh": "我们部门的主管是一位年轻的女士。", "py": "Wǒmen bùmén de zhǔguǎn shì yí wèi niánqīng de nǚshì.", "vi": "Người phụ trách phòng chúng tôi là một phụ nữ trẻ."}}, {"id": "h3-938", "ex": {"zh": "办公室主任负责安排会议。", "py": "Bàngōngshì zhǔrèn fùzé ānpái huìyì.", "vi": "Chánh văn phòng phụ trách sắp xếp các cuộc họp."}}, {"id": "h2-861", "ex": {"zh": "组长把任务分给了每个人。", "py": "Zǔzhǎng bǎ rènwu fēn gěi le měi ge rén.", "vi": "Trưởng nhóm đã chia nhiệm vụ cho từng người."}}, {"id": "h6-825", "ex": {"zh": "我们团队一共有八个人。", "py": "Wǒmen tuánduì yígòng yǒu bā ge rén.", "vi": "Nhóm chúng tôi có tổng cộng tám người."}}, {"id": "h5-442", "ex": {"zh": "明天上午我要去见一个重要的客户。", "py": "Míngtiān shàngwǔ wǒ yào qù jiàn yí ge zhòngyào de kèhù.", "vi": "Sáng mai tôi phải đi gặp một khách hàng quan trọng."}}, {"id": "h0-0003", "ex": {"zh": "新来的实习生学得很快。", "py": "Xīn lái de shíxíshēng xué de hěn kuài.", "vi": "Thực tập sinh mới đến học việc rất nhanh."}}]}, {"name": "Tuyển dụng và nhân sự", "items": [{"id": "h6-1050", "ex": {"zh": "公司正在招聘两名翻译。", "py": "Gōngsī zhèngzài zhāopìn liǎng míng fānyì.", "vi": "Công ty đang tuyển hai phiên dịch viên."}}, {"id": "h7-5022", "ex": {"zh": "我想应聘你们公司的翻译工作。", "py": "Wǒ xiǎng yìngpìn nǐmen gōngsī de fānyì gōngzuò.", "vi": "Tôi muốn ứng tuyển công việc phiên dịch của công ty anh chị."}}, {"id": "h4-519", "ex": {"zh": "明天下午我有一个面试。", "py": "Míngtiān xiàwǔ wǒ yǒu yí ge miànshì.", "vi": "Chiều mai tôi có một buổi phỏng vấn."}}, {"id": "h4-381", "ex": {"zh": "请把你的简历发到这个邮箱。", "py": "Qǐng bǎ nǐ de jiǎnlì fā dào zhège yóuxiāng.", "vi": "Hãy gửi CV của bạn đến hộp thư này."}}, {"id": "h5-1009", "ex": {"zh": "这个职位要求会说中文。", "py": "Zhège zhíwèi yāoqiú huì shuō Zhōngwén.", "vi": "Vị trí này yêu cầu biết nói tiếng Trung."}}, {"id": "h6-304", "ex": {"zh": "新员工要先熟悉自己的岗位。", "py": "Xīn yuángōng yào xiān shúxī zìjǐ de gǎngwèi.", "vi": "Nhân viên mới phải làm quen với vị trí công việc của mình trước."}}, {"id": "h2-585", "ex": {"zh": "他大四的时候在这家公司实习过。", "py": "Tā dà sì de shíhou zài zhè jiā gōngsī shíxí guo.", "vi": "Năm cuối đại học anh ấy từng thực tập ở công ty này."}}, {"id": "h4-551", "ex": {"zh": "新员工要参加一个星期的培训。", "py": "Xīn yuángōng yào cānjiā yí ge xīngqī de péixùn.", "vi": "Nhân viên mới phải tham gia khóa đào tạo một tuần."}}, {"id": "h0-0004", "ex": {"zh": "她工作很努力，今年升职了。", "py": "Tā gōngzuò hěn nǔlì, jīnnián shēngzhí le.", "vi": "Cô ấy làm việc rất chăm chỉ, năm nay được thăng chức."}}, {"id": "h5-140", "ex": {"zh": "他上个月辞职了，准备自己开公司。", "py": "Tā shàng ge yuè cízhí le, zhǔnbèi zìjǐ kāi gōngsī.", "vi": "Tháng trước anh ấy nghỉ việc, định tự mở công ty."}}, {"id": "h7-4101", "ex": {"zh": "现在很多年轻人两三年就跳槽一次。", "py": "Xiànzài hěn duō niánqīngrén liǎng sān nián jiù tiàocáo yí cì.", "vi": "Bây giờ nhiều người trẻ cứ hai ba năm lại nhảy việc một lần."}}, {"id": "h7-2123", "ex": {"zh": "他经常迟到，最后被公司解雇了。", "py": "Tā jīngcháng chídào, zuìhòu bèi gōngsī jiěgù le.", "vi": "Anh ta thường đi muộn, cuối cùng bị công ty sa thải."}}, {"id": "h3-740", "ex": {"zh": "我爸爸明年就要退休了。", "py": "Wǒ bàba míngnián jiù yào tuìxiū le.", "vi": "Sang năm bố tôi sẽ nghỉ hưu."}}, {"id": "h7-3439", "ex": {"zh": "请假的事你要去找人事部。", "py": "Qǐngjià de shì nǐ yào qù zhǎo rénshì bù.", "vi": "Chuyện xin nghỉ thì bạn phải đến phòng nhân sự."}}, {"id": "h0-0011", "ex": {"zh": "她下个星期一正式入职。", "py": "Tā xià ge xīngqīyī zhèngshì rùzhí.", "vi": "Thứ Hai tuần sau cô ấy chính thức vào làm."}}, {"id": "h7-3743", "ex": {"zh": "新员工的试用期是两个月。", "py": "Xīn yuángōng de shìyòngqī shì liǎng ge yuè.", "vi": "Thời gian thử việc của nhân viên mới là hai tháng."}}, {"id": "h0-0012", "ex": {"zh": "试用期结束后，他顺利转正了。", "py": "Shìyòngqī jiéshù hòu, tā shùnlì zhuǎnzhèng le.", "vi": "Hết thời gian thử việc, anh ấy được lên nhân viên chính thức."}}, {"id": "h7-2563", "ex": {"zh": "离职以前，要把工作交接清楚。", "py": "Lízhí yǐqián, yào bǎ gōngzuò jiāojiē qīngchu.", "vi": "Trước khi nghỉ việc phải bàn giao công việc rõ ràng."}}, {"id": "h7-1986", "ex": {"zh": "她周末在一家咖啡店做兼职。", "py": "Tā zhōumò zài yì jiā kāfēi diàn zuò jiānzhí.", "vi": "Cuối tuần cô ấy làm thêm ở một quán cà phê."}}]}, {"name": "Lương, chế độ và đánh giá", "items": [{"id": "h3-244", "ex": {"zh": "我们公司每个月十号发工资。", "py": "Wǒmen gōngsī měi ge yuè shí hào fā gōngzī.", "vi": "Công ty chúng tôi trả lương vào ngày mười hằng tháng."}}, {"id": "h4-388", "ex": {"zh": "年底每个人都能拿到奖金。", "py": "Niándǐ měi ge rén dōu néng nádào jiǎngjīn.", "vi": "Cuối năm ai cũng được nhận tiền thưởng."}}, {"id": "h0-0005", "ex": {"zh": "老板答应明年给大家加薪。", "py": "Lǎobǎn dāying míngnián gěi dàjiā jiāxīn.", "vi": "Sếp hứa sang năm sẽ tăng lương cho mọi người."}}, {"id": "h4-155", "ex": {"zh": "这家公司待遇好，所以很多人想进。", "py": "Zhè jiā gōngsī dàiyù hǎo, suǒyǐ hěn duō rén xiǎng jìn.", "vi": "Công ty này đãi ngộ tốt nên nhiều người muốn vào làm."}}, {"id": "h5-253", "ex": {"zh": "公司的福利包括免费午餐和体检。", "py": "Gōngsī de fúlì bāokuò miǎnfèi wǔcān hé tǐjiǎn.", "vi": "Phúc lợi của công ty gồm bữa trưa miễn phí và khám sức khỏe."}}, {"id": "h3-022", "ex": {"zh": "公司会帮员工交医疗保险。", "py": "Gōngsī huì bāng yuángōng jiāo yīliáo bǎoxiǎn.", "vi": "Công ty đóng bảo hiểm y tế cho nhân viên."}}, {"id": "h1-397", "ex": {"zh": "我明天想请一天假，去看医生。", "py": "Wǒ míngtiān xiǎng qǐng yì tiān jià, qù kàn yīshēng.", "vi": "Mai tôi muốn xin nghỉ một ngày để đi khám bệnh."}}, {"id": "h0-0006", "ex": {"zh": "我还有五天年假没休。", "py": "Wǒ hái yǒu wǔ tiān niánjià méi xiū.", "vi": "Tôi còn năm ngày phép năm chưa nghỉ."}}, {"id": "h2-728", "ex": {"zh": "经理下周休假，有事找他的助理。", "py": "Jīnglǐ xià zhōu xiūjià, yǒu shì zhǎo tā de zhùlǐ.", "vi": "Tuần sau giám đốc nghỉ phép, có việc thì tìm trợ lý của ông ấy."}}, {"id": "h0-0007", "ex": {"zh": "上班的时候别忘了打卡。", "py": "Shàngbān de shíhou bié wàng le dǎkǎ.", "vi": "Lúc đi làm đừng quên chấm công."}}, {"id": "h5-123", "ex": {"zh": "我下周要去上海出差三天。", "py": "Wǒ xià zhōu yào qù Shànghǎi chūchāi sān tiān.", "vi": "Tuần sau tôi phải đi công tác Thượng Hải ba ngày."}}, {"id": "h0-0013", "ex": {"zh": "今年的年终奖是三个月的工资。", "py": "Jīnnián de niánzhōngjiǎng shì sān ge yuè de gōngzī.", "vi": "Thưởng cuối năm nay bằng ba tháng lương."}}, {"id": "h0-0014", "ex": {"zh": "周末加班有加班费吗？", "py": "Zhōumò jiābān yǒu jiābānfèi ma?", "vi": "Cuối tuần tăng ca có được trả tiền làm thêm không?"}}, {"id": "h4-095", "ex": {"zh": "路上堵车，我今天又迟到了。", "py": "Lùshang dǔchē, wǒ jīntiān yòu chídào le.", "vi": "Đường tắc, hôm nay tôi lại đi muộn."}}, {"id": "h5-431", "ex": {"zh": "公司每半年考核一次员工的工作。", "py": "Gōngsī měi bàn nián kǎohé yí cì yuángōng de gōngzuò.", "vi": "Cứ nửa năm công ty đánh giá công việc của nhân viên một lần."}}, {"id": "h0-0015", "ex": {"zh": "奖金的多少要看个人的绩效。", "py": "Jiǎngjīn de duōshao yào kàn gèrén de jìxiào.", "vi": "Thưởng nhiều hay ít phải xem hiệu suất của từng người."}}]}, {"name": "Họp và trao đổi", "items": [{"id": "h3-308", "ex": {"zh": "今天的会议几点开始？", "py": "Jīntiān de huìyì jǐ diǎn kāishǐ?", "vi": "Cuộc họp hôm nay mấy giờ bắt đầu?"}}, {"id": "h1-290", "ex": {"zh": "经理正在开会，请你等一会儿。", "py": "Jīnglǐ zhèngzài kāihuì, qǐng nǐ děng yíhuìr.", "vi": "Giám đốc đang họp, xin bạn đợi một lát."}}, {"id": "h2-620", "ex": {"zh": "我们下午讨论一下这个问题。", "py": "Wǒmen xiàwǔ tǎolùn yíxià zhège wèntí.", "vi": "Chiều nay chúng ta bàn về vấn đề này nhé."}}, {"id": "h3-178", "ex": {"zh": "开会的时候，每个人都要发言。", "py": "Kāihuì de shíhou, měi ge rén dōu yào fāyán.", "vi": "Lúc họp, ai cũng phải phát biểu."}}, {"id": "h4-337", "ex": {"zh": "请你把项目的情况向经理汇报一下。", "py": "Qǐng nǐ bǎ xiàngmù de qíngkuàng xiàng jīnglǐ huìbào yíxià.", "vi": "Bạn hãy báo cáo tình hình dự án với giám đốc."}}, {"id": "h3-027", "ex": {"zh": "这份报告明天上午要交给老板。", "py": "Zhè fèn bàogào míngtiān shàngwǔ yào jiāo gěi lǎobǎn.", "vi": "Bản báo cáo này sáng mai phải nộp cho sếp."}}, {"id": "h3-965", "ex": {"zh": "每个月底要写一份工作总结。", "py": "Měi ge yuèdǐ yào xiě yí fèn gōngzuò zǒngjié.", "vi": "Cuối mỗi tháng phải viết một bản tổng kết công việc."}}, {"id": "h2-765", "ex": {"zh": "大家对这个计划有什么意见？", "py": "Dàjiā duì zhège jìhuà yǒu shénme yìjiàn?", "vi": "Mọi người có ý kiến gì về kế hoạch này?"}}, {"id": "h3-347", "ex": {"zh": "我建议下次开会早点儿通知大家。", "py": "Wǒ jiànyì xià cì kāihuì zǎo diǎnr tōngzhī dàjiā.", "vi": "Tôi đề nghị lần sau họp thì báo mọi người sớm hơn."}}, {"id": "h2-645", "ex": {"zh": "公司通知明天放假一天。", "py": "Gōngsī tōngzhī míngtiān fàngjià yì tiān.", "vi": "Công ty thông báo mai được nghỉ một ngày."}}, {"id": "h3-453", "ex": {"zh": "有问题可以随时跟我联系。", "py": "Yǒu wèntí kěyǐ suíshí gēn wǒ liánxì.", "vi": "Có vấn đề gì có thể liên hệ với tôi bất cứ lúc nào."}}, {"id": "h5-288", "ex": {"zh": "和客户沟通的时候要有耐心。", "py": "Hé kèhù gōutōng de shíhou yào yǒu nàixīn.", "vi": "Khi trao đổi với khách hàng phải kiên nhẫn."}}, {"id": "h1-158", "ex": {"zh": "请你给客户打个电话，问问他什么时候有空。", "py": "Qǐng nǐ gěi kèhù dǎ ge diànhuà, wènwen tā shénme shíhou yǒu kòng.", "vi": "Bạn gọi điện cho khách hàng, hỏi xem khi nào anh ấy rảnh."}}, {"id": "h3-152", "ex": {"zh": "我已经用电子邮件把合同发给你了。", "py": "Wǒ yǐjīng yòng diànzǐ yóujiàn bǎ hétong fā gěi nǐ le.", "vi": "Tôi đã gửi hợp đồng cho bạn qua email rồi."}}, {"id": "h3-936", "ex": {"zh": "今天的会议由王经理主持。", "py": "Jīntiān de huìyì yóu Wáng jīnglǐ zhǔchí.", "vi": "Cuộc họp hôm nay do giám đốc Vương chủ trì."}}, {"id": "h3-322", "ex": {"zh": "开会的时候，请你做一下记录。", "py": "Kāihuì de shíhou, qǐng nǐ zuò yíxià jìlù.", "vi": "Lúc họp, bạn ghi biên bản giúp nhé."}}, {"id": "h0-0016", "ex": {"zh": "每周一早上九点开例会。", "py": "Měi zhōuyī zǎoshang jiǔ diǎn kāi lìhuì.", "vi": "Chín giờ sáng thứ Hai hằng tuần họp giao ban."}}, {"id": "h2-570", "ex": {"zh": "这件事我得先跟同事商量一下。", "py": "Zhè jiàn shì wǒ děi xiān gēn tóngshì shāngliang yíxià.", "vi": "Việc này tôi phải bàn với đồng nghiệp trước."}}, {"id": "h7-1056", "ex": {"zh": "客户的反馈都很好。", "py": "Kèhù de fǎnkuì dōu hěn hǎo.", "vi": "Phản hồi của khách hàng đều rất tốt."}}, {"id": "h2-595", "ex": {"zh": "文件我已经收到了，谢谢！", "py": "Wénjiàn wǒ yǐjīng shōudào le, xièxie!", "vi": "Tài liệu tôi đã nhận được rồi, cảm ơn!"}}]}, {"name": "Nhiệm vụ và tiến độ", "items": [{"id": "h3-601", "ex": {"zh": "这个任务必须在周五前完成。", "py": "Zhège rènwu bìxū zài zhōuwǔ qián wánchéng.", "vi": "Nhiệm vụ này phải hoàn thành trước thứ Sáu."}}, {"id": "h4-804", "ex": {"zh": "他负责公司最大的一个项目。", "py": "Tā fùzé gōngsī zuì dà de yí ge xiàngmù.", "vi": "Anh ấy phụ trách dự án lớn nhất của công ty."}}, {"id": "h2-353", "ex": {"zh": "我们先做一个详细的工作计划。", "py": "Wǒmen xiān zuò yí ge xiángxì de gōngzuò jìhuà.", "vi": "Chúng ta làm một kế hoạch công việc chi tiết trước đã."}}, {"id": "h4-233", "ex": {"zh": "这两个方案你觉得哪个好？", "py": "Zhè liǎng ge fāng'àn nǐ juéde nǎge hǎo?", "vi": "Hai phương án này bạn thấy cái nào tốt hơn?"}}, {"id": "h3-498", "ex": {"zh": "今年的销售目标是一千万。", "py": "Jīnnián de xiāoshòu mùbiāo shì yìqiān wàn.", "vi": "Mục tiêu doanh số năm nay là mười triệu."}}, {"id": "h3-002", "ex": {"zh": "下周的工作我已经安排好了。", "py": "Xià zhōu de gōngzuò wǒ yǐjīng ānpái hǎo le.", "vi": "Công việc tuần sau tôi đã sắp xếp xong rồi."}}, {"id": "h3-208", "ex": {"zh": "这件事由小李负责。", "py": "Zhè jiàn shì yóu Xiǎo Lǐ fùzé.", "vi": "Việc này do Tiểu Lý phụ trách."}}, {"id": "h3-267", "ex": {"zh": "他很会管理时间，很少加班。", "py": "Tā hěn huì guǎnlǐ shíjiān, hěn shǎo jiābān.", "vi": "Anh ấy rất giỏi quản lý thời gian, hiếm khi phải tăng ca."}}, {"id": "h3-108", "ex": {"zh": "我有点儿急事要处理，晚点儿给你回电话。", "py": "Wǒ yǒudiǎnr jíshì yào chǔlǐ, wǎn diǎnr gěi nǐ huí diànhuà.", "vi": "Tôi có chút việc gấp cần xử lý, lát nữa gọi lại cho bạn."}}, {"id": "h2-658", "ex": {"zh": "报告已经完成了，请您看一下。", "py": "Bàogào yǐjīng wánchéng le, qǐng nín kàn yíxià.", "vi": "Báo cáo đã xong rồi, mời anh/chị xem qua."}}, {"id": "h7-2168", "ex": {"zh": "经理每天都要了解项目的进度。", "py": "Jīnglǐ měi tiān dōu yào liǎojiě xiàngmù de jìndù.", "vi": "Ngày nào giám đốc cũng muốn nắm tiến độ dự án."}}, {"id": "h4-811", "ex": {"zh": "开短会可以提高工作效率。", "py": "Kāi duǎn huì kěyǐ tígāo gōngzuò xiàolǜ.", "vi": "Họp ngắn có thể nâng cao hiệu suất làm việc."}}, {"id": "h3-823", "ex": {"zh": "年底工作多，大家压力都很大。", "py": "Niándǐ gōngzuò duō, dàjiā yālì dōu hěn dà.", "vi": "Cuối năm nhiều việc, ai cũng chịu áp lực lớn."}}, {"id": "h6-448", "ex": {"zh": "报名截止到这个星期五。", "py": "Bàomíng jiézhǐ dào zhège xīngqīwǔ.", "vi": "Hạn đăng ký kéo dài đến thứ Sáu tuần này."}}, {"id": "h7-3463", "ex": {"zh": "这是总经理下周的日程安排。", "py": "Zhè shì zǒngjīnglǐ xià zhōu de rìchéng ānpái.", "vi": "Đây là lịch trình tuần sau của tổng giám đốc."}}, {"id": "h4-735", "ex": {"zh": "会议推迟到下午三点。", "py": "Huìyì tuīchí dào xiàwǔ sān diǎn.", "vi": "Cuộc họp lùi đến ba giờ chiều."}}, {"id": "h3-572", "ex": {"zh": "因为经理生病，今天的会取消了。", "py": "Yīnwèi jīnglǐ shēngbìng, jīntiān de huì qǔxiāo le.", "vi": "Vì giám đốc ốm nên cuộc họp hôm nay bị hủy."}}, {"id": "h4-596", "ex": {"zh": "请你再确认一下开会的时间。", "py": "Qǐng nǐ zài quèrèn yíxià kāihuì de shíjiān.", "vi": "Bạn xác nhận lại thời gian họp nhé."}}, {"id": "h3-814", "ex": {"zh": "这份方案还要再修改一下。", "py": "Zhè fèn fāng'àn hái yào zài xiūgǎi yíxià.", "vi": "Phương án này còn phải sửa lại một chút."}}, {"id": "h0-0017", "ex": {"zh": "这个客户由你来跟进。", "py": "Zhège kèhù yóu nǐ lái gēnjìn.", "vi": "Khách hàng này do bạn theo dõi chăm sóc."}}]}, {"name": "Giấy tờ và thiết bị", "items": [{"id": "h3-760", "ex": {"zh": "这份文件需要经理签字。", "py": "Zhè fèn wénjiàn xūyào jīnglǐ qiānzì.", "vi": "Văn bản này cần giám đốc ký."}}, {"id": "h4-985", "ex": {"zh": "开会前请先看一下这些资料。", "py": "Kāihuì qián qǐng xiān kàn yíxià zhèxiē zīliào.", "vi": "Trước khi họp, hãy xem qua những tài liệu này."}}, {"id": "h4-318", "ex": {"zh": "我们和这家公司签了三年的合同。", "py": "Wǒmen hé zhè jiā gōngsī qiān le sān nián de hétong.", "vi": "Chúng tôi đã ký hợp đồng ba năm với công ty này."}}, {"id": "h5-584", "ex": {"zh": "请在这儿签字。", "py": "Qǐng zài zhèr qiānzì.", "vi": "Xin ký tên ở đây."}}, {"id": "h3-047", "ex": {"zh": "请先填一下这张表格。", "py": "Qǐng xiān tián yíxià zhè zhāng biǎogé.", "vi": "Mời điền vào mẫu đơn này trước."}}, {"id": "h4-669", "ex": {"zh": "这些数据是上个月的销售情况。", "py": "Zhèxiē shùjù shì shàng ge yuè de xiāoshòu qíngkuàng.", "vi": "Những số liệu này là tình hình bán hàng tháng trước."}}, {"id": "h6-796", "ex": {"zh": "请在周五以前提交报告。", "py": "Qǐng zài zhōuwǔ yǐqián tíjiāo bàogào.", "vi": "Hãy nộp báo cáo trước thứ Sáu."}}, {"id": "h2-188", "ex": {"zh": "麻烦你帮我把这份合同打印两份。", "py": "Máfan nǐ bāng wǒ bǎ zhè fèn hétong dǎyìn liǎng fèn.", "vi": "Phiền bạn in giúp tôi hợp đồng này hai bản."}}, {"id": "h3-209", "ex": {"zh": "请把身份证复印一下。", "py": "Qǐng bǎ shēnfènzhèng fùyìn yíxià.", "vi": "Hãy photo chứng minh thư một bản."}}, {"id": "h6-184", "ex": {"zh": "打印机没纸了，你去拿点儿纸来。", "py": "Dǎyìnjī méi zhǐ le, nǐ qù ná diǎnr zhǐ lái.", "vi": "Máy in hết giấy rồi, bạn đi lấy ít giấy nhé."}}, {"id": "h0-0008", "ex": {"zh": "复印机坏了，我已经打电话叫人来修了。", "py": "Fùyìnjī huài le, wǒ yǐjīng dǎ diànhuà jiào rén lái xiū le.", "vi": "Máy photo hỏng rồi, tôi đã gọi người đến sửa."}}, {"id": "h1-179", "ex": {"zh": "我的电脑太慢了，得换一台新的。", "py": "Wǒ de diànnǎo tài màn le, děi huàn yì tái xīn de.", "vi": "Máy tính của tôi chậm quá, phải đổi máy mới."}}, {"id": "h4-523", "ex": {"zh": "这是我的名片，有事请联系我。", "py": "Zhè shì wǒ de míngpiàn, yǒu shì qǐng liánxì wǒ.", "vi": "Đây là danh thiếp của tôi, có việc gì xin cứ liên hệ."}}, {"id": "h4-627", "ex": {"zh": "我想申请调到上海的分公司。", "py": "Wǒ xiǎng shēnqǐng diào dào Shànghǎi de fēngōngsī.", "vi": "Tôi muốn xin chuyển sang chi nhánh Thượng Hải."}}, {"id": "h3-533", "ex": {"zh": "我的请假申请经理已经批准了。", "py": "Wǒ de qǐngjià shēnqǐng jīnglǐ yǐjīng pīzhǔn le.", "vi": "Đơn xin nghỉ của tôi giám đốc đã duyệt rồi."}}, {"id": "h4-220", "ex": {"zh": "吃完饭别忘了要发票。", "py": "Chī wán fàn bié wàng le yào fāpiào.", "vi": "Ăn xong đừng quên lấy hóa đơn."}}, {"id": "h7-0116", "ex": {"zh": "出差的车票可以拿回公司报销。", "py": "Chūchāi de chēpiào kěyǐ ná huí gōngsī bàoxiāo.", "vi": "Vé xe đi công tác có thể mang về công ty để thanh toán."}}, {"id": "h0-0018", "ex": {"zh": "合同签字以后还要盖章。", "py": "Hétong qiānzì yǐhòu hái yào gàizhāng.", "vi": "Hợp đồng sau khi ký còn phải đóng dấu."}}, {"id": "h0-0019", "ex": {"zh": "每个星期五下午要交周报。", "py": "Měi ge xīngqīwǔ xiàwǔ yào jiāo zhōubào.", "vi": "Chiều thứ Sáu hằng tuần phải nộp báo cáo tuần."}}]}, {"name": "Kinh doanh và khách hàng", "items": [{"id": "h3-290", "ex": {"zh": "希望我们以后能长期合作。", "py": "Xīwàng wǒmen yǐhòu néng chángqī hézuò.", "vi": "Hy vọng sau này chúng ta có thể hợp tác lâu dài."}}, {"id": "h5-881", "ex": {"zh": "他主要负责海外业务。", "py": "Tā zhǔyào fùzé hǎiwài yèwù.", "vi": "Anh ấy chủ yếu phụ trách mảng kinh doanh nước ngoài."}}, {"id": "h3-655", "ex": {"zh": "我们的产品在越南市场卖得很好。", "py": "Wǒmen de chǎnpǐn zài Yuènán shìchǎng mài de hěn hǎo.", "vi": "Sản phẩm của chúng tôi bán rất chạy ở thị trường Việt Nam."}}, {"id": "h4-807", "ex": {"zh": "她在销售部工作了五年。", "py": "Tā zài xiāoshòu bù gōngzuò le wǔ nián.", "vi": "Cô ấy đã làm ở phòng kinh doanh năm năm."}}, {"id": "h4-073", "ex": {"zh": "下个月我们要推出一款新产品。", "py": "Xià ge yuè wǒmen yào tuīchū yì kuǎn xīn chǎnpǐn.", "vi": "Tháng sau chúng tôi sẽ ra mắt một sản phẩm mới."}}, {"id": "h3-696", "ex": {"zh": "这次谈判进行得很顺利。", "py": "Zhè cì tánpàn jìnxíng de hěn shùnlì.", "vi": "Cuộc đàm phán lần này diễn ra rất suôn sẻ."}}, {"id": "h5-582", "ex": {"zh": "双方明天上午正式签约。", "py": "Shuāngfāng míngtiān shàngwǔ zhèngshì qiānyuē.", "vi": "Sáng mai hai bên chính thức ký hợp đồng."}}, {"id": "h7-0888", "ex": {"zh": "这个月的订单比上个月多了一倍。", "py": "Zhège yuè de dìngdān bǐ shàng ge yuè duō le yí bèi.", "vi": "Đơn hàng tháng này gấp đôi tháng trước."}}, {"id": "h0-0020", "ex": {"zh": "请把最新的报价发给客户。", "py": "Qǐng bǎ zuì xīn de bàojià fā gěi kèhù.", "vi": "Hãy gửi bảng báo giá mới nhất cho khách hàng."}}, {"id": "h7-1207", "ex": {"zh": "客户说下周一付款。", "py": "Kèhù shuō xià zhōuyī fùkuǎn.", "vi": "Khách hàng nói thứ Hai tuần sau sẽ thanh toán."}}, {"id": "h7-5118", "ex": {"zh": "这个项目的预算不够了。", "py": "Zhège xiàngmù de yùsuàn bú gòu le.", "vi": "Ngân sách của dự án này không đủ nữa."}}, {"id": "h5-469", "ex": {"zh": "今年公司的利润增加了百分之二十。", "py": "Jīnnián gōngsī de lìrùn zēngjiā le bǎi fēn zhī èrshí.", "vi": "Năm nay lợi nhuận công ty tăng 20%."}}]}, {"name": "Máy tính và email", "items": [{"id": "h3-858", "ex": {"zh": "你的工作邮箱是多少？", "py": "Nǐ de gōngzuò yóuxiāng shì duōshao?", "vi": "Email công việc của bạn là gì?"}}, {"id": "h3-177", "ex": {"zh": "报告写好以后直接发送给经理。", "py": "Bàogào xiě hǎo yǐhòu zhíjiē fāsòng gěi jīnglǐ.", "vi": "Viết xong báo cáo thì gửi thẳng cho giám đốc."}}, {"id": "h4-335", "ex": {"zh": "收到邮件请尽快回复。", "py": "Shōudào yóujiàn qǐng jǐnkuài huífù.", "vi": "Nhận được email xin trả lời sớm."}}, {"id": "h5-256", "ex": {"zh": "合同在邮件的附件里。", "py": "Hétong zài yóujiàn de fùjiàn li.", "vi": "Hợp đồng nằm trong tệp đính kèm của email."}}, {"id": "h0-0021", "ex": {"zh": "我把客户的邮件转发给你了。", "py": "Wǒ bǎ kèhù de yóujiàn zhuǎnfā gěi nǐ le.", "vi": "Tôi đã chuyển tiếp email của khách hàng cho bạn."}}, {"id": "h4-515", "ex": {"zh": "电脑的密码要三个月换一次。", "py": "Diànnǎo de mìmǎ yào sān ge yuè huàn yí cì.", "vi": "Mật khẩu máy tính phải ba tháng đổi một lần."}}, {"id": "h7-5257", "ex": {"zh": "新员工会收到一个系统账号。", "py": "Xīn yuángōng huì shōudào yí ge xìtǒng zhànghào.", "vi": "Nhân viên mới sẽ nhận được một tài khoản hệ thống."}}, {"id": "h5-635", "ex": {"zh": "公司要求大家用这个软件开视频会议。", "py": "Gōngsī yāoqiú dàjiā yòng zhège ruǎnjiàn kāi shìpín huìyì.", "vi": "Công ty yêu cầu mọi người dùng phần mềm này để họp trực tuyến."}}, {"id": "h4-781", "ex": {"zh": "系统出了问题，现在没法打卡。", "py": "Xìtǒng chū le wèntí, xiànzài méi fǎ dǎkǎ.", "vi": "Hệ thống gặp sự cố, giờ không chấm công được."}}, {"id": "h4-746", "ex": {"zh": "今天办公室的网络特别慢。", "py": "Jīntiān bàngōngshì de wǎngluò tèbié màn.", "vi": "Hôm nay mạng ở văn phòng chậm kinh khủng."}}]}]}, {"id": "t-dulich", "title": "Du lịch", "hz": "旅游", "desc": "Từ vựng cho chuyến đi: lên kế hoạch, sân bay, tàu xe, khách sạn, hỏi đường, tham quan, ăn uống mua sắm và xử lý sự cố.", "groups": [{"name": "Lên kế hoạch và giấy tờ", "items": [{"id": "h2-469", "ex": {"zh": "这个假期你打算去哪儿旅游？", "py": "Zhège jiàqī nǐ dǎsuan qù nǎr lǚyóu?", "vi": "Kỳ nghỉ này bạn định đi du lịch ở đâu?"}}, {"id": "h2-468", "ex": {"zh": "我想一个人去中国旅行。", "py": "Wǒ xiǎng yí ge rén qù Zhōngguó lǚxíng.", "vi": "Tôi muốn đi du lịch Trung Quốc một mình."}}, {"id": "h2-361", "ex": {"zh": "假期只有五天，不能去太远的地方。", "py": "Jiàqī zhǐ yǒu wǔ tiān, bù néng qù tài yuǎn de dìfang.", "vi": "Kỳ nghỉ chỉ có năm ngày, không đi chỗ quá xa được."}}, {"id": "h2-353", "ex": {"zh": "我们计划下个月去北京玩儿。", "py": "Wǒmen jìhuà xià ge yuè qù Běijīng wánr.", "vi": "Chúng tôi dự định tháng sau đi Bắc Kinh chơi."}}, {"id": "h6-910", "ex": {"zh": "这次的行程安排得很满。", "py": "Zhè cì de xíngchéng ānpái de hěn mǎn.", "vi": "Lịch trình chuyến này sắp xếp rất kín."}}, {"id": "h2-168", "ex": {"zh": "明天早上六点从酒店出发。", "py": "Míngtiān zǎoshang liù diǎn cóng jiǔdiàn chūfā.", "vi": "Sáu giờ sáng mai xuất phát từ khách sạn."}}, {"id": "h2-169", "ex": {"zh": "这是我第一次出国旅游。", "py": "Zhè shì wǒ dì-yī cì chūguó lǚyóu.", "vi": "Đây là lần đầu tôi đi du lịch nước ngoài."}}, {"id": "h2-331", "ex": {"zh": "出国以前，先看看护照有没有过期。", "py": "Chūguó yǐqián, xiān kànkan hùzhào yǒu méiyǒu guòqī.", "vi": "Trước khi ra nước ngoài, xem hộ chiếu có hết hạn chưa."}}, {"id": "h5-583", "ex": {"zh": "去中国旅游需要办签证。", "py": "Qù Zhōngguó lǚyóu xūyào bàn qiānzhèng.", "vi": "Du lịch Trung Quốc cần làm thị thực."}}, {"id": "h4-907", "ex": {"zh": "我已经在网上预订了酒店。", "py": "Wǒ yǐjīng zài wǎngshang yùdìng le jiǔdiàn.", "vi": "Tôi đã đặt khách sạn trên mạng rồi."}}, {"id": "h3-467", "ex": {"zh": "这次旅游是通过旅行社报名的。", "py": "Zhè cì lǚyóu shì tōngguò lǚxíngshè bàomíng de.", "vi": "Chuyến du lịch này đăng ký qua công ty lữ hành."}}, {"id": "h4-166", "ex": {"zh": "导游给我们介绍了这里的历史。", "py": "Dǎoyóu gěi wǒmen jièshào le zhèlǐ de lìshǐ.", "vi": "Hướng dẫn viên giới thiệu cho chúng tôi lịch sử nơi này."}}, {"id": "h2-782", "ex": {"zh": "周末来长城的游客特别多。", "py": "Zhōumò lái Chángchéng de yóukè tèbié duō.", "vi": "Cuối tuần du khách đến Vạn Lý Trường Thành rất đông."}}, {"id": "h0-0022", "ex": {"zh": "出发前我在网上看了很多攻略。", "py": "Chūfā qián wǒ zài wǎngshang kàn le hěn duō gōnglüè.", "vi": "Trước khi đi tôi đã xem rất nhiều bài kinh nghiệm du lịch trên mạng."}}, {"id": "h0-0023", "ex": {"zh": "跟团旅游比较省心。", "py": "Gēntuán lǚyóu bǐjiào shěngxīn.", "vi": "Đi theo tour thì đỡ phải lo hơn."}}, {"id": "h0-0024", "ex": {"zh": "年轻人更喜欢自由行。", "py": "Niánqīngrén gèng xǐhuan zìyóuxíng.", "vi": "Người trẻ thích đi du lịch tự túc hơn."}}]}, {"name": "Sân bay và máy bay", "items": [{"id": "h1-262", "ex": {"zh": "我们提前两个小时到机场吧。", "py": "Wǒmen tíqián liǎng ge xiǎoshí dào jīchǎng ba.", "vi": "Chúng ta đến sân bay sớm hai tiếng nhé."}}, {"id": "h1-207", "ex": {"zh": "从河内坐飞机到北京要三个多小时。", "py": "Cóng Hénèi zuò fēijī dào Běijīng yào sān ge duō xiǎoshí.", "vi": "Đi máy bay từ Hà Nội đến Bắc Kinh mất hơn ba tiếng."}}, {"id": "h4-311", "ex": {"zh": "您的航班几点起飞？", "py": "Nín de hángbān jǐ diǎn qǐfēi?", "vi": "Chuyến bay của anh/chị mấy giờ cất cánh?"}}, {"id": "h1-263", "ex": {"zh": "节假日的机票很贵。", "py": "Jiéjiàrì de jīpiào hěn guì.", "vi": "Vé máy bay dịp lễ rất đắt."}}, {"id": "h7-0803", "ex": {"zh": "请乘客们到十二号门登机。", "py": "Qǐng chéngkèmen dào shí'èr hào mén dēngjī.", "vi": "Mời hành khách lên máy bay ở cửa số mười hai."}}, {"id": "h0-0025", "ex": {"zh": "请出示您的护照和登机牌。", "py": "Qǐng chūshì nín de hùzhào hé dēngjīpái.", "vi": "Xin xuất trình hộ chiếu và thẻ lên máy bay."}}, {"id": "h2-530", "ex": {"zh": "飞机马上就要起飞了，请关手机。", "py": "Fēijī mǎshàng jiù yào qǐfēi le, qǐng guān shǒujī.", "vi": "Máy bay sắp cất cánh, xin tắt điện thoại."}}, {"id": "h4-393", "ex": {"zh": "飞机已经安全降落了。", "py": "Fēijī yǐjīng ānquán jiàngluò le.", "vi": "Máy bay đã hạ cánh an toàn."}}, {"id": "h4-743", "ex": {"zh": "因为下大雨，飞机晚点了一个小时。", "py": "Yīnwèi xià dàyǔ, fēijī wǎndiǎn le yí ge xiǎoshí.", "vi": "Vì mưa to nên máy bay trễ một tiếng."}}, {"id": "h7-4768", "ex": {"zh": "由于天气原因，航班延误了。", "py": "Yóuyú tiānqì yuányīn, hángbān yánwù le.", "vi": "Do thời tiết, chuyến bay bị hoãn."}}, {"id": "h7-5491", "ex": {"zh": "我们要在广州转机。", "py": "Wǒmen yào zài Guǎngzhōu zhuǎnjī.", "vi": "Chúng tôi phải đổi chuyến bay ở Quảng Châu."}}, {"id": "h6-004", "ex": {"zh": "过安检的时候，水不能带进去。", "py": "Guò ānjiǎn de shíhou, shuǐ bù néng dài jìnqu.", "vi": "Khi qua kiểm tra an ninh, không được mang nước vào."}}, {"id": "h0-0026", "ex": {"zh": "这个大箱子需要托运。", "py": "Zhège dà xiāngzi xūyào tuōyùn.", "vi": "Cái vali to này cần ký gửi."}}, {"id": "h3-803", "ex": {"zh": "我的行李太多了，拿不动。", "py": "Wǒ de xíngli tài duō le, ná bu dòng.", "vi": "Hành lý của tôi nhiều quá, xách không nổi."}}, {"id": "h0-0027", "ex": {"zh": "我的行李箱是蓝色的。", "py": "Wǒ de xínglixiāng shì lánsè de.", "vi": "Vali của tôi màu xanh lam."}}, {"id": "h3-281", "ex": {"zh": "入境的时候要过海关。", "py": "Rùjìng de shíhou yào guò hǎiguān.", "vi": "Khi nhập cảnh phải qua hải quan."}}]}, {"name": "Tàu xe và đi lại", "items": [{"id": "h1-261", "ex": {"zh": "我们坐晚上的火车去西安。", "py": "Wǒmen zuò wǎnshang de huǒchē qù Xī'ān.", "vi": "Chúng tôi đi tàu hỏa buổi tối đến Tây An."}}, {"id": "h4-267", "ex": {"zh": "从北京坐高铁到上海只要四个多小时。", "py": "Cóng Běijīng zuò gāotiě dào Shànghǎi zhǐ yào sì ge duō xiǎoshí.", "vi": "Đi tàu cao tốc từ Bắc Kinh đến Thượng Hải chỉ hơn bốn tiếng."}}, {"id": "h1-145", "ex": {"zh": "酒店离火车站不远。", "py": "Jiǔdiàn lí huǒchēzhàn bù yuǎn.", "vi": "Khách sạn cách ga tàu không xa."}}, {"id": "h6-1041", "ex": {"zh": "请到三号站台上车。", "py": "Qǐng dào sān hào zhàntái shàngchē.", "vi": "Mời lên tàu ở sân ga số ba."}}, {"id": "h1-143", "ex": {"zh": "五一的车票很难买。", "py": "Wǔ-Yī de chēpiào hěn nán mǎi.", "vi": "Vé tàu dịp 1/5 rất khó mua."}}, {"id": "h2-869", "ex": {"zh": "我的座位在窗户旁边。", "py": "Wǒ de zuòwèi zài chuānghu pángbiān.", "vi": "Chỗ ngồi của tôi ở cạnh cửa sổ."}}, {"id": "h2-225", "ex": {"zh": "坐地铁去故宫最方便。", "py": "Zuò dìtiě qù Gùgōng zuì fāngbiàn.", "vi": "Đi tàu điện ngầm đến Cố Cung là tiện nhất."}}, {"id": "h2-176", "ex": {"zh": "我们叫一辆出租车去机场吧。", "py": "Wǒmen jiào yí liàng chūzūchē qù jīchǎng ba.", "vi": "Chúng ta gọi taxi ra sân bay đi."}}, {"id": "h1-157", "ex": {"zh": "这里离景点很远，还是打车吧。", "py": "Zhèlǐ lí jǐngdiǎn hěn yuǎn, háishi dǎchē ba.", "vi": "Từ đây đến điểm tham quan xa lắm, hay là đi taxi."}}, {"id": "h2-289", "ex": {"zh": "坐公交车去海边要一个小时。", "py": "Zuò gōngjiāochē qù hǎibiān yào yí ge xiǎoshí.", "vi": "Đi xe buýt ra biển mất một tiếng."}}, {"id": "h2-606", "ex": {"zh": "司机，请在前面停一下。", "py": "Sījī, qǐng zài qiánmian tíng yíxià.", "vi": "Bác tài ơi, dừng ở phía trước giúp tôi."}}, {"id": "h5-111", "ex": {"zh": "各位乘客，前方到站是天安门东。", "py": "Gèwèi chéngkè, qiánfāng dào zhàn shì Tiān'ānmén Dōng.", "vi": "Kính thưa quý hành khách, ga tiếp theo là Thiên An Môn Đông."}}, {"id": "h4-202", "ex": {"zh": "节假日去景区经常堵车。", "py": "Jiéjiàrì qù jǐngqū jīngcháng dǔchē.", "vi": "Ngày lễ đi khu du lịch thường bị tắc đường."}}, {"id": "h0-0028", "ex": {"zh": "我们在岛上租车自己开。", "py": "Wǒmen zài dǎo shang zūchē zìjǐ kāi.", "vi": "Chúng tôi thuê xe tự lái trên đảo."}}, {"id": "h7-4269", "ex": {"zh": "往返机票比单程便宜一点儿。", "py": "Wǎngfǎn jīpiào bǐ dānchéng piányi yìdiǎnr.", "vi": "Vé máy bay khứ hồi rẻ hơn một chiều một chút."}}, {"id": "h0-0029", "ex": {"zh": "我只买了一张单程票。", "py": "Wǒ zhǐ mǎi le yì zhāng dānchéng piào.", "vi": "Tôi chỉ mua một vé một chiều."}}]}, {"name": "Khách sạn", "items": [{"id": "h2-402", "ex": {"zh": "这家酒店就在海边，风景很好。", "py": "Zhè jiā jiǔdiàn jiù zài hǎibiān, fēngjǐng hěn hǎo.", "vi": "Khách sạn này ở ngay bờ biển, cảnh rất đẹp."}}, {"id": "h5-041", "ex": {"zh": "学校附近有几家便宜的宾馆。", "py": "Xuéxiào fùjìn yǒu jǐ jiā piányi de bīnguǎn.", "vi": "Gần trường có mấy nhà nghỉ giá rẻ."}}, {"id": "h7-5468", "ex": {"zh": "这次旅行，住宿费是多少？", "py": "Zhè cì lǚxíng, zhùsù fèi shì duōshao?", "vi": "Chuyến đi này tiền ở là bao nhiêu?"}}, {"id": "h0-0030", "ex": {"zh": "我们在古镇住了一家民宿。", "py": "Wǒmen zài gǔzhèn zhù le yì jiā mínsù.", "vi": "Chúng tôi ở một homestay trong thị trấn cổ."}}, {"id": "h1-201", "ex": {"zh": "我想要一个能看到海的房间。", "py": "Wǒ xiǎng yào yí ge néng kàndào hǎi de fángjiān.", "vi": "Tôi muốn một phòng nhìn ra biển."}}, {"id": "h0-0031", "ex": {"zh": "下午两点以后才能入住。", "py": "Xiàwǔ liǎng diǎn yǐhòu cái néng rùzhù.", "vi": "Sau hai giờ chiều mới được nhận phòng."}}, {"id": "h0-0032", "ex": {"zh": "明天中午十二点以前要退房。", "py": "Míngtiān zhōngwǔ shí'èr diǎn yǐqián yào tuìfáng.", "vi": "Trưa mai trước mười hai giờ phải trả phòng."}}, {"id": "h0-0033", "ex": {"zh": "单人间一晚三百块。", "py": "Dānrénjiān yì wǎn sānbǎi kuài.", "vi": "Phòng đơn ba trăm tệ một đêm."}}, {"id": "h0-0034", "ex": {"zh": "还有双人间吗？", "py": "Hái yǒu shuāngrénjiān ma?", "vi": "Còn phòng đôi không?"}}, {"id": "h7-3259", "ex": {"zh": "有问题可以打电话给前台。", "py": "Yǒu wèntí kěyǐ dǎ diànhuà gěi qiántái.", "vi": "Có vấn đề gì thì gọi điện cho lễ tân."}}, {"id": "h5-868", "ex": {"zh": "入住的时候要交两百块押金。", "py": "Rùzhù de shíhou yào jiāo liǎngbǎi kuài yājīn.", "vi": "Khi nhận phòng phải đặt cọc hai trăm tệ."}}, {"id": "h0-0035", "ex": {"zh": "我把房卡忘在房间里了。", "py": "Wǒ bǎ fángkǎ wàng zài fángjiān li le.", "vi": "Tôi để quên thẻ phòng trong phòng rồi."}}, {"id": "h7-4847", "ex": {"zh": "你拿房间钥匙了吗？", "py": "Nǐ ná fángjiān yàoshi le ma?", "vi": "Bạn cầm chìa khóa phòng chưa?"}}, {"id": "h2-806", "ex": {"zh": "酒店的早餐从七点开始。", "py": "Jiǔdiàn de zǎocān cóng qī diǎn kāishǐ.", "vi": "Bữa sáng của khách sạn bắt đầu từ bảy giờ."}}, {"id": "h4-501", "ex": {"zh": "请再给我们两条毛巾。", "py": "Qǐng zài gěi wǒmen liǎng tiáo máojīn.", "vi": "Cho chúng tôi thêm hai cái khăn tắm."}}, {"id": "h3-421", "ex": {"zh": "房间的空调坏了，能帮我看看吗？", "py": "Fángjiān de kōngtiáo huài le, néng bāng wǒ kànkan ma?", "vi": "Điều hòa trong phòng hỏng rồi, xem giúp tôi được không?"}}]}, {"name": "Hỏi đường", "items": [{"id": "h1-173", "ex": {"zh": "你看一下手机上的地图。", "py": "Nǐ kàn yíxià shǒujī shang de dìtú.", "vi": "Bạn xem bản đồ trên điện thoại đi."}}, {"id": "h7-0770", "ex": {"zh": "开车的时候用手机导航很方便。", "py": "Kāichē de shíhou yòng shǒujī dǎoháng hěn fāngbiàn.", "vi": "Lái xe dùng điện thoại chỉ đường rất tiện."}}, {"id": "h4-185", "ex": {"zh": "请把酒店的地址发给我。", "py": "Qǐng bǎ jiǔdiàn de dìzhǐ fā gěi wǒ.", "vi": "Gửi cho tôi địa chỉ khách sạn nhé."}}, {"id": "h4-257", "ex": {"zh": "请问，附近有地铁站吗？", "py": "Qǐngwèn, fùjìn yǒu dìtiězhàn ma?", "vi": "Xin hỏi, gần đây có ga tàu điện ngầm không?"}}, {"id": "h2-444", "ex": {"zh": "博物馆离这儿远吗？", "py": "Bówùguǎn lí zhèr yuǎn ma?", "vi": "Bảo tàng cách đây có xa không?"}}, {"id": "h1-551", "ex": {"zh": "不远，走路十分钟就到了。", "py": "Bù yuǎn, zǒulù shí fēnzhōng jiù dào le.", "vi": "Không xa, đi bộ mười phút là tới."}}, {"id": "h2-669", "ex": {"zh": "往前走，到路口往左拐。", "py": "Wǎng qián zǒu, dào lùkǒu wǎng zuǒ guǎi.", "vi": "Đi thẳng về phía trước, đến ngã tư rẽ trái."}}, {"id": "h2-763", "ex": {"zh": "一直往前走，就能看到公园。", "py": "Yìzhí wǎng qián zǒu, jiù néng kàndào gōngyuán.", "vi": "Cứ đi thẳng là thấy công viên."}}, {"id": "h6-341", "ex": {"zh": "在第二个路口往右拐。", "py": "Zài dì-èr ge lùkǒu wǎng yòu guǎi.", "vi": "Đến ngã tư thứ hai thì rẽ phải."}}, {"id": "h1-322", "ex": {"zh": "我在前面的路口等你。", "py": "Wǒ zài qiánmian de lùkǒu děng nǐ.", "vi": "Tôi đợi bạn ở ngã tư phía trước."}}, {"id": "h2-247", "ex": {"zh": "酒店对面就是一家超市。", "py": "Jiǔdiàn duìmiàn jiù shì yì jiā chāoshì.", "vi": "Đối diện khách sạn là một siêu thị."}}, {"id": "h2-261", "ex": {"zh": "我们是不是走错方向了？", "py": "Wǒmen shì bu shì zǒu cuò fāngxiàng le?", "vi": "Có phải chúng ta đi nhầm hướng rồi không?"}}, {"id": "h7-2849", "ex": {"zh": "我在老城区迷路了。", "py": "Wǒ zài lǎo chéngqū mílù le.", "vi": "Tôi bị lạc đường trong khu phố cổ."}}, {"id": "h2-677", "ex": {"zh": "找不到地方可以向别人问路。", "py": "Zhǎo bu dào dìfang kěyǐ xiàng biérén wènlù.", "vi": "Không tìm được chỗ thì có thể hỏi đường người khác."}}]}, {"name": "Tham quan", "items": [{"id": "h6-469", "ex": {"zh": "西湖是杭州最有名的景点。", "py": "Xī Hú shì Hángzhōu zuì yǒumíng de jǐngdiǎn.", "vi": "Tây Hồ là điểm tham quan nổi tiếng nhất Hàng Châu."}}, {"id": "h4-246", "ex": {"zh": "这里的风景太美了！", "py": "Zhèlǐ de fēngjǐng tài měi le!", "vi": "Phong cảnh ở đây đẹp quá!"}}, {"id": "h3-388", "ex": {"zh": "山上的景色特别漂亮。", "py": "Shān shang de jǐngsè tèbié piàoliang.", "vi": "Cảnh sắc trên núi đặc biệt đẹp."}}, {"id": "h1-340", "ex": {"zh": "故宫的门票要提前在网上买。", "py": "Gùgōng de ménpiào yào tíqián zài wǎngshang mǎi.", "vi": "Vé vào Cố Cung phải mua trước trên mạng."}}, {"id": "h2-508", "ex": {"zh": "买票的人很多，我们排队排了半个小时。", "py": "Mǎi piào de rén hěn duō, wǒmen páiduì pái le bàn ge xiǎoshí.", "vi": "Người mua vé đông, chúng tôi xếp hàng nửa tiếng."}}, {"id": "h2-148", "ex": {"zh": "下午我们去参观博物馆。", "py": "Xiàwǔ wǒmen qù cānguān bówùguǎn.", "vi": "Chiều nay chúng tôi đi tham quan bảo tàng."}}, {"id": "h7-5066", "ex": {"zh": "游览这个公园要两个小时左右。", "py": "Yóulǎn zhège gōngyuán yào liǎng ge xiǎoshí zuǒyòu.", "vi": "Dạo chơi công viên này mất khoảng hai tiếng."}}, {"id": "h5-049", "ex": {"zh": "博物馆每周一不开门。", "py": "Bówùguǎn měi zhōuyī bù kāimén.", "vi": "Bảo tàng đóng cửa vào thứ Hai hằng tuần."}}, {"id": "h6-588", "ex": {"zh": "这座城市有很多名胜。", "py": "Zhè zuò chéngshì yǒu hěn duō míngshèng.", "vi": "Thành phố này có rất nhiều danh thắng."}}, {"id": "h7-1410", "ex": {"zh": "西安到处都是历史古迹。", "py": "Xī'ān dàochù dōu shì lìshǐ gǔjì.", "vi": "Tây An đâu đâu cũng là di tích lịch sử."}}, {"id": "h7-3922", "ex": {"zh": "山上有一座很老的寺庙。", "py": "Shān shang yǒu yí zuò hěn lǎo de sìmiào.", "vi": "Trên núi có một ngôi chùa rất cổ."}}, {"id": "h2-312", "ex": {"zh": "我们每天早上去海边散步。", "py": "Wǒmen měi tiān zǎoshang qù hǎibiān sànbù.", "vi": "Sáng nào chúng tôi cũng ra bờ biển đi dạo."}}, {"id": "h7-3530", "ex": {"zh": "孩子们在沙滩上玩儿得很开心。", "py": "Háizimen zài shātān shang wánr de hěn kāixīn.", "vi": "Bọn trẻ chơi trên bãi cát rất vui."}}, {"id": "h6-205", "ex": {"zh": "坐船去岛上要四十分钟。", "py": "Zuò chuán qù dǎo shang yào sìshí fēnzhōng.", "vi": "Đi thuyền ra đảo mất bốn mươi phút."}}, {"id": "h2-505", "ex": {"zh": "明天早上我们去爬山看日出。", "py": "Míngtiān zǎoshang wǒmen qù pá shān kàn rìchū.", "vi": "Sáng mai chúng tôi đi leo núi ngắm mặt trời mọc."}}, {"id": "h4-545", "ex": {"zh": "这里不能拍照。", "py": "Zhèlǐ bù néng pāizhào.", "vi": "Ở đây không được chụp ảnh."}}, {"id": "h2-819", "ex": {"zh": "我在长城拍了很多照片。", "py": "Wǒ zài Chángchéng pāi le hěn duō zhàopiàn.", "vi": "Tôi đã chụp rất nhiều ảnh ở Vạn Lý Trường Thành."}}, {"id": "h7-1613", "ex": {"zh": "我们在大门前合影吧。", "py": "Wǒmen zài dàmén qián héyǐng ba.", "vi": "Chúng ta chụp ảnh chung trước cổng nhé."}}, {"id": "h0-0036", "ex": {"zh": "她喜欢在每个景点自拍。", "py": "Tā xǐhuan zài měi ge jǐngdiǎn zìpāi.", "vi": "Cô ấy thích chụp ảnh selfie ở mỗi điểm tham quan."}}, {"id": "h7-4861", "ex": {"zh": "晚上我们去夜市吃东西吧。", "py": "Wǎnshang wǒmen qù yèshì chī dōngxi ba.", "vi": "Tối nay chúng ta đi chợ đêm ăn uống nhé."}}]}, {"name": "Ăn uống và mua sắm", "items": [{"id": "h3-138", "ex": {"zh": "到了一个地方，一定要尝尝当地的菜。", "py": "Dàole yí ge dìfang, yídìng yào chángchang dāngdì de cài.", "vi": "Đến một nơi thì nhất định phải nếm thử món ăn địa phương."}}, {"id": "h7-4041", "ex": {"zh": "这是云南的特产，带回去送朋友吧。", "py": "Zhè shì Yúnnán de tèchǎn, dài huíqu sòng péngyou ba.", "vi": "Đây là đặc sản Vân Nam, mang về tặng bạn bè đi."}}, {"id": "h4-808", "ex": {"zh": "这条街上有很多有名的小吃。", "py": "Zhè tiáo jiē shang yǒu hěn duō yǒumíng de xiǎochī.", "vi": "Con phố này có rất nhiều món ăn vặt nổi tiếng."}}, {"id": "h3-483", "ex": {"zh": "成都是一座美食城市。", "py": "Chéngdū shì yí zuò měishí chéngshì.", "vi": "Thành Đô là một thành phố ẩm thực."}}, {"id": "h5-094", "ex": {"zh": "你尝尝这个，特别好吃。", "py": "Nǐ chángchang zhège, tèbié hǎochī.", "vi": "Bạn nếm thử món này đi, ngon lắm."}}, {"id": "h7-0831", "ex": {"zh": "这家店的北京烤鸭很地道。", "py": "Zhè jiā diàn de Běijīng kǎoyā hěn dìdao.", "vi": "Vịt quay Bắc Kinh của quán này rất chuẩn vị."}}, {"id": "h2-147", "ex": {"zh": "服务员，请给我们看一下菜单。", "py": "Fúwùyuán, qǐng gěi wǒmen kàn yíxià càidān.", "vi": "Phục vụ ơi, cho chúng tôi xem thực đơn."}}, {"id": "h0-0037", "ex": {"zh": "你来点菜吧，我什么都吃。", "py": "Nǐ lái diǎncài ba, wǒ shénme dōu chī.", "vi": "Bạn gọi món đi, tôi ăn gì cũng được."}}, {"id": "h0-0038", "ex": {"zh": "服务员，买单！", "py": "Fúwùyuán, mǎidān!", "vi": "Phục vụ ơi, tính tiền!"}}, {"id": "h0-0039", "ex": {"zh": "我给家人买了一些纪念品。", "py": "Wǒ gěi jiārén mǎi le yìxiē jìniànpǐn.", "vi": "Tôi mua ít quà lưu niệm cho gia đình."}}, {"id": "h4-283", "ex": {"zh": "很多游客来香港是为了购物。", "py": "Hěn duō yóukè lái Xiānggǎng shì wèile gòuwù.", "vi": "Nhiều du khách đến Hồng Kông là để mua sắm."}}, {"id": "h4-139", "ex": {"zh": "商场里的衣服都在打折。", "py": "Shāngchǎng li de yīfu dōu zài dǎzhé.", "vi": "Quần áo trong trung tâm thương mại đều đang giảm giá."}}, {"id": "h0-0040", "ex": {"zh": "在小商店买东西可以讲价。", "py": "Zài xiǎo shāngdiàn mǎi dōngxi kěyǐ jiǎngjià.", "vi": "Mua đồ ở cửa hàng nhỏ có thể mặc cả."}}, {"id": "h2-514", "ex": {"zh": "太贵了，能便宜一点儿吗？", "py": "Tài guì le, néng piányi yìdiǎnr ma?", "vi": "Đắt quá, bớt chút được không?"}}, {"id": "h3-782", "ex": {"zh": "这家小店只收现金。", "py": "Zhè jiā xiǎo diàn zhǐ shōu xiànjīn.", "vi": "Cửa hàng nhỏ này chỉ nhận tiền mặt."}}, {"id": "h0-0041", "ex": {"zh": "这里可以刷卡吗？", "py": "Zhèlǐ kěyǐ shuākǎ ma?", "vi": "Ở đây quẹt thẻ được không?"}}, {"id": "h0-0042", "ex": {"zh": "在机场换钱不太划算。", "py": "Zài jīchǎng huànqián bú tài huásuàn.", "vi": "Đổi tiền ở sân bay không lợi lắm."}}, {"id": "h4-338", "ex": {"zh": "今天人民币的汇率是多少？", "py": "Jīntiān rénmínbì de huìlǜ shì duōshao?", "vi": "Tỷ giá nhân dân tệ hôm nay là bao nhiêu?"}}]}, {"name": "Sự cố và lưu ý", "items": [{"id": "h5-206", "ex": {"zh": "我的钱包在地铁上丢了。", "py": "Wǒ de qiánbāo zài dìtiě shang diū le.", "vi": "Tôi bị mất ví trên tàu điện ngầm."}}, {"id": "h1-395", "ex": {"zh": "小心你的钱包，这里人很多。", "py": "Xiǎoxīn nǐ de qiánbāo, zhèlǐ rén hěn duō.", "vi": "Cẩn thận ví tiền, ở đây đông người."}}, {"id": "h3-899", "ex": {"zh": "请带好您的证件。", "py": "Qǐng dài hǎo nín de zhèngjiàn.", "vi": "Xin mang theo giấy tờ tùy thân."}}, {"id": "h5-016", "ex": {"zh": "护照丢了要马上报警。", "py": "Hùzhào diū le yào mǎshàng bàojǐng.", "vi": "Mất hộ chiếu phải báo cảnh sát ngay."}}, {"id": "h3-389", "ex": {"zh": "有问题可以找警察帮忙。", "py": "Yǒu wèntí kěyǐ zhǎo jǐngchá bāngmáng.", "vi": "Có chuyện gì có thể nhờ cảnh sát giúp."}}, {"id": "h3-128", "ex": {"zh": "护照丢了，要去大使馆办新的。", "py": "Hùzhào diū le, yào qù dàshǐguǎn bàn xīn de.", "vi": "Mất hộ chiếu thì phải đến đại sứ quán làm cái mới."}}, {"id": "h3-022", "ex": {"zh": "出国旅游最好买一份保险。", "py": "Chūguó lǚyóu zuìhǎo mǎi yí fèn bǎoxiǎn.", "vi": "Đi du lịch nước ngoài tốt nhất nên mua bảo hiểm."}}, {"id": "h1-429", "ex": {"zh": "旅行的时候生病了真麻烦。", "py": "Lǚxíng de shíhou shēngbìng le zhēn máfan.", "vi": "Đang đi du lịch mà ốm thì thật phiền."}}, {"id": "h6-1020", "ex": {"zh": "我坐长途汽车容易晕车。", "py": "Wǒ zuò chángtú qìchē róngyì yùnchē.", "vi": "Tôi đi xe khách đường dài dễ bị say xe."}}, {"id": "h0-0043", "ex": {"zh": "刚到美国，我还没倒过来时差。", "py": "Gāng dào Měiguó, wǒ hái méi dǎo guòlai shíchā.", "vi": "Vừa đến Mỹ, tôi vẫn chưa quen lệch múi giờ."}}, {"id": "h4-101", "ex": {"zh": "我忘了带手机充电器。", "py": "Wǒ wàng le dài shǒujī chōngdiànqì.", "vi": "Tôi quên mang sạc điện thoại."}}, {"id": "h2-718", "ex": {"zh": "山上没有信号，打不了电话。", "py": "Shān shang méiyǒu xìnhào, dǎ bu liǎo diànhuà.", "vi": "Trên núi không có sóng, không gọi điện được."}}, {"id": "h2-105", "ex": {"zh": "晚上一个人出去要注意安全。", "py": "Wǎnshang yí ge rén chūqu yào zhùyì ānquán.", "vi": "Buổi tối ra ngoài một mình phải chú ý an toàn."}}, {"id": "h2-706", "ex": {"zh": "下雨了，路很滑，小心点儿。", "py": "Xià yǔ le, lù hěn huá, xiǎoxīn diǎnr.", "vi": "Trời mưa đường trơn, cẩn thận nhé."}}]}]}];
